`default_nettype none
module ishi_logo(input wire [6:0] h,input wire [9:0] v,output wire [2:0] rgb);
wire [1:0] c=~h[5:4];
wire [2:0] x=~h[3:1];
wire [2:0] y=v[7:5] ^ 3'b100;
wire glyph=((~y[0] & ~y[1] & ~y[2] & ~x[0] & x[1] & ~x[2]) | (c[0] & ~c[1] & y[0] & y[1] & ~y[2] & ~x[1] & x[2]) | (c[0] & ~c[1] & ~y[0] & y[1] & x[0] & ~x[1] & ~x[2]) | (~c[0] & ~c[1] & ~y[1] & ~x[0] & ~x[1] & x[2]) | (y[0] & y[1] & ~y[2] & x[0] & x[1] & ~x[2]) | (c[0] & c[1] & ~y[0] & x[0] & x[1] & ~x[2]) | (c[0] & ~c[1] & ~y[1] & y[2] & x[0] & ~x[1] & x[2]) | (~c[0] & ~c[1] & ~y[1] & x[0] & x[1] & ~x[2]) | (c[0] & ~c[1] & ~y[0] & ~y[1] & ~y[2] & ~x[0] & x[2]) | (~c[0] & c[1] & ~y[0] & ~x[0] & x[1]) | (c[0] & c[1] & ~y[2] & ~x[0] & ~x[1] & x[2]) | (~c[0] & ~c[1] & ~y[0] & x[0] & x[1] & ~x[2]) | (~y[0] & ~y[1] & ~y[2] & x[0] & ~x[1] & x[2]) | (~y[0] & y[1] & y[2] & ~x[0] & x[1] & ~x[2]) | (c[0] & ~y[0] & y[1] & y[2] & ~x[1] & x[2]) | (~c[0] & ~c[1] & ~y[2] & ~x[0] & ~x[1] & x[2]) | (~c[1] & ~y[0] & y[1] & y[2] & ~x[1] & x[2]) | (~c[0] & c[1] & ~y[1] & x[0] & ~x[1]) | (c[0] & ~c[1] & ~y[1] & y[2] & ~x[0] & x[1] & x[2]) | (~c[0] & c[1] & ~y[2] & ~x[0] & x[1]) | (~c[0] & c[1] & ~y[1] & ~x[0] & x[1]) | (c[0] & ~c[1] & ~y[2] & ~x[0] & x[1] & ~x[2]) | (c[0] & c[1] & ~y[1] & x[0] & x[1] & ~x[2]) | (y[0] & y[1] & ~y[2] & ~x[0] & ~x[1] & x[2]) | (c[0] & ~c[1] & y[0] & ~y[1] & ~y[2] & x[0] & ~x[1] & ~x[2]) | (~c[1] & ~y[0] & ~y[1] & ~y[2] & x[1] & ~x[2]) | (~c[0] & c[1] & ~y[2] & x[0] & ~x[1]) | (~c[0] & c[1] & ~y[0] & x[0] & ~x[1]) | (~c[1] & ~y[0] & y[1] & y[2] & x[1] & ~x[2]) | (c[0] & c[1] & ~y[1] & ~x[0] & ~x[1] & x[2]));
wire in_logo=~h[6];
wire red=in_logo && (v>=10'd640) && (v<10'd864) && glyph;
wire cyan=in_logo && ((v[9:4]==6'd37) || (v[9:4]==6'd56));
wire blue=in_logo && (v[9:5]==5'd21);
wire purple=in_logo && (v[9:5]==5'd25);
assign rgb=red ? 3'b100 : cyan ? 3'b011 : blue ? 3'b001 : purple ? 3'b101 : 3'b111;
endmodule
`default_nettype wire
